/**
 * Keep token-rate provider events from forcing token-rate component renders.
 * The latest cumulative snapshot is delivered once per animation frame.
 */
export function createFrameCoalescer<T>(callback: (value: T) => void): {
  push: (value: T) => void;
  flush: () => void;
  cancel: () => void;
} {
  let pending: T | undefined;
  let scheduled = false;
  let frame: number | null = null;

  const deliver = () => {
    scheduled = false;
    frame = null;
    if (pending === undefined) return;
    const value = pending;
    pending = undefined;
    callback(value);
  };

  return {
    push(value) {
      pending = value;
      if (scheduled) return;
      scheduled = true;
      if (typeof requestAnimationFrame === "function") {
        frame = requestAnimationFrame(deliver);
      } else {
        queueMicrotask(deliver);
      }
    },
    flush() {
      if (frame !== null && typeof cancelAnimationFrame === "function") {
        cancelAnimationFrame(frame);
      }
      deliver();
    },
    cancel() {
      if (frame !== null && typeof cancelAnimationFrame === "function") {
        cancelAnimationFrame(frame);
      }
      frame = null;
      scheduled = false;

