      personaNotes?: PushPayload["personaNotes"];
      personaReplies?: PushPayload["personaReplies"];
      rubricResults?: PushPayload["rubricResults"];
      bibliography?: PushPayload["bibliography"];
    } | null {
  const briefs = changedRows(next.briefs, previous?.briefs, (b) => b.folioId);
  const folioContent = changedRows(
    next.folioContent,
    previous?.folioContent,
    (c) => c.folioId,
